import {test,expect,type Page} from '@playwright/test';
import fs from 'node:fs';
const fixture=()=>JSON.parse(fs.readFileSync(process.env.CPLANE_SNAPSHOT_FILE!,'utf8'));
const reviewAck='I have reviewed the evidence, all human test results and unresolved limitations.';
async function start(page:Page){await page.goto('/overview');await page.getByRole('checkbox',{name:'I have read the system summary and limitations.'}).check();await page.getByRole('button',{name:/Continue to Evidence/}).click();}
async function inspect(page:Page,count=14){for(let i=1;i<=count;i++){await page.locator('details.gate-card').filter({has:page.locator('summary strong',{hasText:new RegExp('^R3\\.'+i+'$')})}).locator('summary').click();const button=page.getByRole('button',{name:'I have inspected R3.'+i+' source',exact:true});if(await button.isEnabled())await button.click();}}
async function evidence(page:Page){await start(page);await inspect(page);await page.getByRole('checkbox',{name:'I have inspected all gate sources and read their limitations.'}).check();await page.getByRole('button',{name:/Continue to Human Test/}).click();}
async function tests(page:Page,result='✓ PASS'){for(const group of await page.getByRole('group',{name:/^Result for /}).all())await group.getByRole('button',{name:result,exact:true}).click();await page.getByRole('button',{name:/Review human results/}).click();}
async function review(page:Page){await page.getByRole('checkbox',{name:reviewAck}).check();await page.getByRole('button',{name:/Continue to Decision/}).click();}
for(const path of ['/evidence','/test','/review','/decision'])test('direct '+path+' is locked without upstream completion',async({page})=>{await page.route('**/v1/control-plane/snapshot',r=>r.fulfill({json:fixture()}));await page.goto(path);await expect(page.getByRole('region',{name:'Locked stage'})).toContainText('Acknowledge the System');await expect(page.getByRole('button',{name:'APPROVE',exact:true})).toHaveCount(0);await expect(page.getByRole('list',{name:'Human acceptance progress'})).toContainText('Locked');await page.getByRole('button',{name:'Go to System →'}).click();await expect(page.getByRole('heading',{name:'System',exact:true})).toBeVisible();});
test('all five transitions require explicit completion and confirmation; no backend mutation',async({page})=>{
  if(process.env.CPLANE_E2E_LIVE!=='1')await page.route('**/v1/control-plane/snapshot',r=>r.fulfill({json:fixture()}));
  const mutations:string[]=[];const errors:string[]=[];page.on('request',r=>{if(r.url().includes('/v1/')&&r.method()!=='GET')mutations.push(r.method());});page.on('pageerror',e=>errors.push(e.message));
  await page.goto('/overview');if(process.env.CPLANE_HUMAN_SCREENSHOT)await page.screenshot({path:process.env.CPLANE_HUMAN_SCREENSHOT.replace('mobile','desktop'),fullPage:true});await expect(page.getByRole('button',{name:'Evidence Locked',exact:true})).toBeDisabled();await expect(page.getByRole('button',{name:/Continue to Evidence/})).toBeDisabled();await expect(page.getByRole('button',{name:/Open Human Decision/})).toBeDisabled();
  await page.getByRole('button',{name:/Inspect runtime evidence/}).click();await expect(page.getByRole('heading',{name:'Runtime',exact:true})).toBeVisible();await page.getByRole('link',{name:'System',exact:true}).click();
  await page.getByRole('checkbox',{name:'I have read the system summary and limitations.'}).check();await expect(page.getByRole('list',{name:'Human acceptance progress'})).toContainText('Available');await page.getByRole('button',{name:/Continue to Evidence/}).click();
  await expect(page.getByRole('list',{name:'Human acceptance progress'})).toContainText('Completed');await inspect(page,13);const evidenceAck=page.getByRole('checkbox',{name:'I have inspected all gate sources and read their limitations.'});await expect(evidenceAck).toBeDisabled();await expect(page.getByRole('button',{name:'Human Test Locked',exact:true})).toBeDisabled();
  await page.locator('details.gate-card').filter({has:page.locator('summary strong',{hasText:'R3.14'})}).locator('summary').click();await page.getByRole('button',{name:'I have inspected R3.14 source',exact:true}).click();await expect(evidenceAck).toBeEnabled();await expect(evidenceAck).not.toBeChecked();await expect(page.getByRole('button',{name:/Continue to Human Test/})).toBeDisabled();await evidenceAck.check();await page.getByRole('button',{name:/Continue to Human Test/}).click();
  await expect(page.getByText('○ NOT TESTED',{exact:true})).toHaveCount(8);const groups=await page.getByRole('group',{name:/^Result for /}).all();for(const group of groups.slice(0,7))await group.getByRole('button',{name:'✓ PASS',exact:true}).click();await expect(page.getByRole('button',{name:/Review human results/})).toBeDisabled();await expect(page.getByRole('button',{name:'Review Locked',exact:true})).toBeDisabled();await groups[7].getByRole('button',{name:'✓ PASS',exact:true}).click();
  await page.getByRole('link',{name:/N NUSANTARA HUMAN ACCEPTANCE CONSOLE/}).click();await page.getByRole('link',{name:'Human Test',exact:true}).click();await expect(page.getByRole('group',{name:'Result for open'}).getByRole('button',{name:'✓ PASS',exact:true})).toHaveAttribute('aria-pressed','true');await page.getByRole('button',{name:/Review human results/}).click();
  await expect(page.getByRole('heading',{name:'Known limitations',exact:true})).toBeVisible();await expect(page.getByText('○ NOT VERIFIED',{exact:true})).toBeVisible();await expect(page.getByRole('button',{name:'Decision Locked',exact:true})).toBeDisabled();await expect(page.getByRole('checkbox',{name:reviewAck})).not.toBeChecked();await expect(page.getByRole('button',{name:/Continue to Decision/})).toBeDisabled();await review(page);
  await expect(page.getByRole('button',{name:'PASS',exact:true})).toBeDisabled();await expect(page.getByRole('button',{name:'FAIL',exact:true})).toBeDisabled();await expect(page.getByRole('button',{name:'HOLD',exact:true})).toBeDisabled();
  await page.getByRole('button',{name:'Refresh evidence',exact:true}).click();await expect(page.getByRole('button',{name:'PASS',exact:true})).toBeDisabled();expect(mutations).toEqual([]);expect(errors).toEqual([]);await page.reload();await expect(page.getByRole('region',{name:'Locked stage'})).toContainText('Acknowledge the System');
});
// Obsolete: this case exercised the retired session-only decision UI (APPROVE/REJECT with a
// mandatory reason). The current decision step is server-bound and operator-token gated; its
// coverage lives in control-plane/tests/human.test.tsx and the /review-execute page tests.
for(const decision of ['REJECT','HOLD'])test.fixme(decision+' follows review of explicit FAIL/BLOCKED and requires a reason',async({page})=>{await page.route('**/v1/control-plane/snapshot',r=>r.fulfill({json:fixture()}));await evidence(page);await tests(page,decision==='REJECT'?'✕ FAIL':'! BLOCKED');await review(page);await expect(page.getByRole('button',{name:'APPROVE',exact:true})).toBeDisabled();await page.getByRole('button',{name:decision,exact:true}).click();const save=page.getByRole('button',{name:decision==='REJECT'?'Confirm Rejection':'Save HOLD',exact:true});await expect(save).toBeDisabled();await page.getByRole('radio',{name:'Other',exact:true}).check();await expect(save).toBeDisabled();await page.getByRole('textbox',{name:'Notes (required)'}).fill('Need human review');await save.click();await expect(page.getByText('Human decision recorded in this session',{exact:true})).toBeVisible();await expect(page.getByText('○ NOT VERIFIED',{exact:true})).toBeVisible();});
test('withdrawing Evidence acknowledgement relocks Test Review Decision',async({page})=>{await page.route('**/v1/control-plane/snapshot',r=>r.fulfill({json:fixture()}));await evidence(page);await tests(page);await review(page);await page.getByRole('link',{name:'Evidence',exact:true}).click();await page.getByRole('checkbox',{name:'I have inspected all gate sources and read their limitations.'}).uncheck();for(const name of ['Human Test','Review','Decision'])await expect(page.getByRole('button',{name:name+' Locked',exact:true})).toBeDisabled();});
test('changing and clearing results invalidates Review acknowledgement and locks downstream',async({page})=>{await page.route('**/v1/control-plane/snapshot',r=>r.fulfill({json:fixture()}));await evidence(page);await tests(page);await review(page);await page.getByRole('link',{name:'Human Test',exact:true}).click();const group=page.getByRole('group',{name:'Result for open'});await group.getByRole('button',{name:'✕ FAIL',exact:true}).click();await expect(page.getByRole('button',{name:'Decision Locked',exact:true})).toBeDisabled();await page.getByRole('link',{name:'Review',exact:true}).click();await expect(page.getByRole('checkbox',{name:reviewAck})).not.toBeChecked();await page.getByRole('link',{name:'Human Test',exact:true}).click();await group.getByRole('button',{name:'Clear result',exact:true}).click();await expect(page.getByRole('button',{name:'Review Locked',exact:true})).toBeDisabled();});
test('withdrawing System acknowledgement relocks every downstream stage',async({page})=>{await page.route('**/v1/control-plane/snapshot',r=>r.fulfill({json:fixture()}));await evidence(page);await tests(page);await review(page);await page.getByRole('link',{name:'System',exact:true}).click();await page.getByRole('checkbox',{name:'I have read the system summary and limitations.'}).uncheck();for(const name of ['Evidence','Human Test','Review','Decision'])await expect(page.getByRole('button',{name:name+' Locked',exact:true})).toBeDisabled();});
test('missing evidence source cannot unlock Test',async({page})=>{const s=fixture();s.gates.find((g:{id:string})=>g.id==='R3.1').evidence=['missing'];await page.route('**/v1/control-plane/snapshot',r=>r.fulfill({json:s}));await start(page);await inspect(page);await expect(page.getByText(/13 of 14 gates inspected/)).toBeVisible();await expect(page.getByRole('checkbox',{name:'I have inspected all gate sources and read their limitations.'})).toBeDisabled();});
test('material evidence changes invalidate the entire session but timestamp-only refresh preserves it',async({page})=>{let snapshot=fixture();await page.route('**/v1/control-plane/snapshot',r=>r.fulfill({json:snapshot}));await evidence(page);await tests(page);await review(page);snapshot={...snapshot,timestamp:new Date().toISOString()};await page.getByRole('button',{name:'Refresh evidence',exact:true}).click();await expect(page.getByRole('region',{name:'Locked stage'})).toHaveCount(0);snapshot={...snapshot,gates:snapshot.gates.map((g:{id:string})=>g.id==='R3.1'?{...g,status:'UNKNOWN'}:g)};await page.getByRole('button',{name:'Refresh evidence',exact:true}).click();await expect(page.getByRole('region',{name:'Locked stage'})).toContainText('Acknowledge the System');await page.getByRole('button',{name:'Go to System →'}).click();await expect(page.getByRole('checkbox',{name:'I have read the system summary and limitations.'})).not.toBeChecked();});
test('unavailable evidence never exposes decision controls',async({page})=>{await page.route('**/v1/control-plane/snapshot',r=>r.fulfill({status:503,json:{error:'unavailable'}}));await page.goto('/decision');await expect(page.getByRole('alert')).toContainText('No healthy state has been inferred');await expect(page.getByRole('button',{name:'APPROVE',exact:true})).toHaveCount(0);await expect(page.getByRole('list',{name:'Human acceptance progress'})).toContainText('Locked');});
test('mobile persistent progress shows states without overflow',async({page})=>{await page.route('**/v1/control-plane/snapshot',r=>r.fulfill({json:fixture()}));await page.setViewportSize({width:390,height:844});await page.goto('/overview');await expect(page.getByRole('list',{name:'Human acceptance progress'})).toContainText('Current');await expect(page.getByRole('button',{name:'Human Test Locked',exact:true})).toBeDisabled();expect(await page.evaluate(()=>document.documentElement.scrollWidth<=window.innerWidth)).toBe(true);if(process.env.CPLANE_HUMAN_SCREENSHOT)await page.screenshot({path:process.env.CPLANE_HUMAN_SCREENSHOT,fullPage:true});});
test('checklist text and alternate System button unlock Evidence only through explicit human action',async({page})=>{
  await page.route('**/v1/control-plane/snapshot',r=>r.fulfill({json:fixture()}));await page.goto('/overview');
  const checkbox=page.getByRole('checkbox',{name:'I have read the system summary and limitations.'});await expect(checkbox).not.toBeChecked();
  const label=page.locator('label').filter({has:checkbox});await label.click();await expect(checkbox).toBeChecked();await expect(page.getByRole('link',{name:'Evidence',exact:true})).toBeVisible();
  await label.click();await expect(checkbox).not.toBeChecked();await expect(page.getByRole('button',{name:'Evidence Locked',exact:true})).toBeDisabled();
  await page.getByRole('button',{name:'Acknowledge System',exact:true}).click();await expect(checkbox).toBeChecked();await page.getByRole('button',{name:/Continue to Evidence/}).click();await expect(page.getByRole('heading',{name:'Evidence',exact:true})).toBeVisible();await expect(page.getByRole('button',{name:'Human Test Locked',exact:true})).toBeDisabled();
});
test('slow background refresh does not disable System checklist or infer acknowledgement',async({page})=>{
  let hold=false;let release!:()=>void;const pending=new Promise<void>(resolve=>{release=resolve;});await page.route('**/v1/control-plane/snapshot',async r=>{if(hold)await pending;await r.fulfill({json:fixture()});});
  await page.goto('/overview');const checkbox=page.getByRole('checkbox',{name:'I have read the system summary and limitations.'});await expect(checkbox).toBeEnabled();hold=true;
  await page.getByRole('button',{name:'Refresh evidence',exact:true}).click();await expect(page.getByRole('button',{name:'Reading evidence…',exact:true})).toBeVisible();await expect(checkbox).not.toBeChecked();await checkbox.click();await expect(checkbox).toBeChecked();await expect(page.getByRole('button',{name:/Continue to Evidence/})).toBeDisabled();release();await expect(page.getByRole('button',{name:/Continue to Evidence/})).toBeEnabled();
});
